  CHECK ("size_bytes" > 0 AND "size_bytes" <= 20971520);

-- Row-Level Security: every Stage 6 table is visible and writable only inside the active tenant.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'documents', 'document_versions', 'consents', 'resource_shares', 'share_documents'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I USING (tenant_id = app_setting_uuid(''app.tenant_id'')) WITH CHECK (tenant_id = app_setting_uuid(''app.tenant_id''))',
      t || '_isolation', t);
  END LOOP;
END $$;

-- File versions are never changed or removed by the API user (new uploads add a version).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'crm_app') THEN
    REVOKE UPDATE, DELETE ON "document_versions" FROM crm_app;
  END IF;
END $$;

-- Default document categories for existing workspaces. Keep in sync with
-- packages/contracts/src/reference-defaults.ts.
DO $$
DECLARE t RECORD;
BEGIN
  FOR t IN SELECT id FROM "tenants" LOOP
    PERFORM set_config('app.tenant_id', t.id::text, true);
    INSERT INTO "reference_options" ("id", "tenant_id", "category", "key", "name", "sort_order", "updated_at")
    SELECT gen_random_uuid(), t.id, 'DOCUMENT_CATEGORY'::"ReferenceCategory", d.key, d.name, d.sort_order, now()
    FROM (VALUES
      ('identity', 'Identity', 1),
      ('financial', 'Financial', 2),
      ('education', 'Education', 3),
      ('employment', 'Employment', 4),
      ('relationship', 'Relationship', 5),
      ('correspondence', 'Correspondence', 6),
      ('other', 'Other', 99)
    ) AS d(key, name, sort_order)
    ON CONFLICT ("tenant_id", "category", "key") DO NOTHING;
  END LOOP;
  PERFORM set_config('app.tenant_id', '', true);
END $$;
